import React from "react";

const money = (value) => {

  return `$${Math.abs(
    Number(value || 0)
  ).toFixed(2)}`;

};

function TransactionHistory({
  transactions = [],
}) {

  if (transactions.length === 0) {

    return (

      <div className="empty-state compact">

        <h3>
          No Transactions
        </h3>

        <p>
          Your transaction history
          will appear here.
        </p>

      </div>

    );
  }

  const sortedTransactions =
    [...transactions].sort(
      (a, b) =>
        new Date(
          b.transactionDate
        ) -
        new Date(
          a.transactionDate
        )
    );

  return (

    <div className="table-card">

      <div className="table-scroll">

        <table>

          <thead>

            <tr>

              <th>
                Date
              </th>

              <th>
                Type
              </th>

              <th>
                Description
              </th>

              <th>
                Recipient
              </th>

              <th>
                Amount
              </th>

            </tr>

          </thead>

          <tbody>

            {sortedTransactions.map(
              (transaction) => {

                const type =
                  transaction.transactionType;

                const isOutgoing =
                  type === "WITHDRAWAL" ||
                  type === "TRANSFER";

                return (

                  <tr
                    key={
                      transaction.transactionId
                    }
                  >

                    <td>

                      {transaction.transactionDate
                        ? new Date(
                            transaction.transactionDate
                          ).toLocaleString()
                        : "—"}

                    </td>

                    <td>

                      <span
                        className={`tx-badge ${
                          type
                            ? type.toLowerCase()
                            : ""
                        }`}
                      >
                        {type}
                      </span>

                    </td>

                    <td>
                      {transaction.description ||
                        "—"}
                    </td>

                    <td>
                      {transaction.recipientAccountId ||
                        "—"}
                    </td>

                    <td
                      className={
                        isOutgoing
                          ? "amount-out"
                          : "amount-in"
                      }
                    >

                      {isOutgoing
                        ? `-${money(
                            transaction.amount
                          )}`
                        : `+${money(
                            transaction.amount
                          )}`}

                    </td>

                  </tr>

                );

              }
            )}

          </tbody>

        </table>

      </div>

    </div>
  );
}

export default TransactionHistory;
